// Synthetic disc fixtures for the export tests. Nothing here is game data: every byte is generated by a test from a
// seeded generator, and none of the editor's own codec code is used to build or to check a fixture.
//
//  * referenceMode1Sector / referenceMode1Problems  CD-ROM MODE1 EDC and ECC written from ECMA-130 (bitwise CRC with
//    the generator polynomial multiplied out, and the P/Q Reed-Solomon parity solved from the two parity-check
//    equations), not the table-driven code of the editor.
//  * tsrStream  a token writer for the TSR compression format, with every token form selectable.
//  * packGreedy  a small LZ packer that also finds length-2 references. It stands in for the stronger compressor of
//    the real build: it packs data the editor's own compressTsr cannot pack as small.
//  * buildDisc / makeSession  a one-directory MODE1/2352 ISO9660 volume around a TSR.BIN slot, and the editor session
//    object that inspectPatchedImage would produce for it.
import { createHash } from 'node:crypto';

import { buildEditorRows, locateIsoFiles, splitRootSegments } from '../../assets/editor-core.mjs';

export const SECTOR = 2352;
export const USER = 2048;

// ---------------------------------------------------------------------------------------------------------------------
// Seeded bytes

export function mulberry32(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function randomBytes(length, seed) {
  const next = mulberry32(seed);
  return Uint8Array.from({ length }, () => Math.floor(next() * 256));
}

export const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');
export const sameBytes = (left, right) => left.length === right.length && Buffer.from(left).equals(Buffer.from(right));

// ---------------------------------------------------------------------------------------------------------------------
// MODE1 EDC / ECC reference

// EDC generator (x^16 + x^15 + x^2 + 1)(x^16 + x^2 + x + 1): multiply it out, then reflect it for the LSB-first CRC.
const EDC_POLYNOMIAL = (() => {
  const multiply = (a, b) => {
    let product = 0n;
    for (let bit = 0n; bit < 17n; bit += 1n) if ((b >> bit) & 1n) product ^= a << bit;
    return product;
  };
  const low = Number(multiply((1n << 16n) | (1n << 15n) | (1n << 2n) | 1n, (1n << 16n) | (1n << 2n) | (1n << 1n) | 1n) & 0xffffffffn);
  let reflected = 0;
  for (let bit = 0; bit < 32; bit += 1) reflected = (reflected << 1) | ((low >>> bit) & 1);
  return reflected >>> 0;
})();

function referenceEdc(bytes) {
  let crc = 0;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit += 1) crc = (crc >>> 1) ^ ((crc & 1) ? EDC_POLYNOMIAL : 0);
  }
  return crc >>> 0;
}

// GF(2^8) with x^8 + x^4 + x^3 + x^2 + 1 and alpha = 2.
const GF_EXP = new Uint8Array(512);
const GF_LOG = new Uint8Array(256);
{
  let value = 1;
  for (let power = 0; power < 255; power += 1) {
    GF_EXP[power] = value;
    GF_LOG[value] = power;
    value <<= 1;
    if (value & 0x100) value ^= 0x11d;
  }
  for (let power = 255; power < 512; power += 1) GF_EXP[power] = GF_EXP[power - 255];
}
const gfMul = (a, b) => (a === 0 || b === 0 ? 0 : GF_EXP[GF_LOG[a] + GF_LOG[b]]);
const gfDiv = (a, b) => (a === 0 ? 0 : GF_EXP[GF_LOG[a] + 255 - GF_LOG[b]]);

// A codeword c_0..c_(n-1) satisfies S0 = sum c_i = 0 and S1 = sum alpha^(n-1-i) c_i = 0; the last two symbols are the
// parity. Given the data symbols the two parity symbols follow from those two equations.
function syndromes(symbols, count = symbols.length) {
  let s0 = 0;
  let s1 = 0;
  symbols.forEach((symbol, index) => {
    s0 ^= symbol;
    s1 ^= gfMul(GF_EXP[count - 1 - index], symbol);
  });
  return [s0, s1];
}

function parityOf(data) {
  const [s0, s1] = syndromes(data, data.length + 2);
  const first = gfDiv(s0 ^ s1, 3); // alpha + 1
  return [first, s0 ^ first];
}

// 16-bit words counted from byte 12 of the sector; half 0 / 1 is the low / high byte of every word.
// P: 43 columns of 24 words, parity words 1032+c and 1075+c. Q: 26 diagonals of 43 words over data and P, parity words
// 1118+d and 1144+d.
const wordByte = (word, half) => 12 + word * 2 + half;
const pWords = (column) => Array.from({ length: 24 }, (_, row) => 43 * row + column);
const pParity = (column) => [1032 + column, 1075 + column];
const qWords = (diagonal) => Array.from({ length: 43 }, (_, k) => (43 * diagonal + 44 * k) % 1118);
const qParity = (diagonal) => [1118 + diagonal, 1144 + diagonal];

function applyChecksums(sector) {
  const edc = referenceEdc(sector.subarray(0, 2064));
  new DataView(sector.buffer, sector.byteOffset).setUint32(2064, edc, true);
  sector.fill(0, 2068, 2076);
  return applyReferenceParity(sector);
}

function applyReferenceParity(sector) {
  for (let half = 0; half < 2; half += 1) {
    for (let column = 0; column < 43; column += 1) {
      const parity = parityOf(pWords(column).map((word) => sector[wordByte(word, half)]));
      pParity(column).forEach((word, index) => { sector[wordByte(word, half)] = parity[index]; });
    }
  }
  for (let half = 0; half < 2; half += 1) {
    for (let diagonal = 0; diagonal < 26; diagonal += 1) {
      const parity = parityOf(qWords(diagonal).map((word) => sector[wordByte(word, half)]));
      qParity(diagonal).forEach((word, index) => { sector[wordByte(word, half)] = parity[index]; });
    }
  }
  return sector;
}

const bcd = (value) => ((Math.floor(value / 10) << 4) | (value % 10));

export function referenceMode1Sector(lba, user) {
  const sector = new Uint8Array(SECTOR);
  sector.fill(0xff, 1, 11);
  const absolute = lba + 150;
  sector[12] = bcd(Math.floor(absolute / 4500));
  sector[13] = bcd(Math.floor(absolute / 75) % 60);
  sector[14] = bcd(absolute % 75);
  sector[15] = 1;
  sector.set(user, 16);
  return applyChecksums(sector);
}

// Names every way a sector fails: framing, EDC, reserved bytes, and each P / Q codeword that has a non-zero syndrome.
export function referenceMode1Problems(sector) {
  const problems = [];
  if (sector.length !== SECTOR) return ['length'];
  if (sector[0] !== 0 || sector[11] !== 0 || sector.subarray(1, 11).some((byte) => byte !== 0xff) || sector[15] !== 1) problems.push('sync/mode');
  const stored = new DataView(sector.buffer, sector.byteOffset).getUint32(2064, true);
  if (stored !== referenceEdc(sector.subarray(0, 2064))) problems.push('edc');
  if (sector.subarray(2068, 2076).some((byte) => byte !== 0)) problems.push('reserved');
  return [...problems, ...referenceParityProblems(sector)];
}

function referenceParityProblems(sector) {
  const problems = [];
  for (let half = 0; half < 2; half += 1) {
    for (let column = 0; column < 43; column += 1) {
      const words = [...pWords(column), ...pParity(column)];
      if (syndromes(words.map((word) => sector[wordByte(word, half)])).some(Boolean)) problems.push(`p${half}:${column}`);
    }
    for (let diagonal = 0; diagonal < 26; diagonal += 1) {
      const words = [...qWords(diagonal), ...qParity(diagonal)];
      if (syndromes(words.map((word) => sector[wordByte(word, half)])).some(Boolean)) problems.push(`q${half}:${diagonal}`);
    }
  }
  return problems;
}

// XA Form 1: the independent GF syndrome checker uses a zero address/mode
// header, while the CRC covers the duplicated subheader and 2048 user bytes.
export function referenceMode2Form1Sector(lba, user, subheader = [3, 7, 0x08, 0]) {
  const sector = referenceMode1Sector(lba, new Uint8Array(2048));
  sector[15] = 2;
  sector.set(subheader, 16); sector.set(subheader, 20);
  sector.set(user, 24);
  new DataView(sector.buffer).setUint32(2072, referenceEdc(sector.subarray(16, 2072)), true);
  const header = sector.slice(12, 16);
  sector.fill(0, 12, 16); applyReferenceParity(sector); sector.set(header, 12);
  return sector;
}

export function referenceMode2Form1Problems(sector) {
  if (sector.length !== SECTOR) return ['length'];
  const problems = [];
  if (sector[0] !== 0 || sector[11] !== 0 || sector.subarray(1, 11).some(byte => byte !== 0xff)
    || sector[15] !== 2) problems.push('sync/mode');
  if (sector[18] & 0x20 || sector.subarray(16, 20).some((byte, index) => byte !== sector[20 + index])) problems.push('subheader/form');
  if (new DataView(sector.buffer, sector.byteOffset).getUint32(2072, true)
    !== referenceEdc(sector.subarray(16, 2072))) problems.push('edc');
  const candidate = sector.slice(); candidate.fill(0, 12, 16);
  return [...problems, ...referenceParityProblems(candidate)];
}

// ---------------------------------------------------------------------------------------------------------------------
// TSR stream writer
//
// Flag bits are consumed MSB first. The flag byte that holds them sits in the stream at the place where the decoder
// needs its first bit, so it comes before the data bytes of the tokens it describes.
//   { literal }            1, byte
//   { near: [dist, len] }  0 0 len-2 (2 bits), byte 256-dist           dist 1..256, len 2..5
//   { word: [dist, len] }  0 1, word (8192-dist)<<3 | len-2             len 3..9
//   { ext: [dist, len] }   0 1, word (8192-dist)<<3, byte len-1         len 2..256, any distance
//   { end: true, endWord } 0 1, word, byte 0                            the word (low three bits zero) keeps its distance bits
export function tsrStream(tokens, { padBits = 0 } = {}) {
  const out = [];
  let flagIndex = -1;
  let used = 8;
  const bit = (value) => {
    if (used === 8) {
      flagIndex = out.length;
      out.push(0);
      used = 0;
    }
    out[flagIndex] |= (value & 1) << (7 - used);
    used += 1;
  };
  const word = (value) => out.push((value >> 8) & 0xff, value & 0xff);
  for (const token of tokens) {
    if (token.literal !== undefined) {
      bit(1);
      out.push(token.literal);
    } else if (token.near) {
      const [distance, length] = token.near;
      bit(0); bit(0); bit(((length - 2) >> 1) & 1); bit((length - 2) & 1);
      out.push(256 - distance);
    } else if (token.word) {
      const [distance, length] = token.word;
      bit(0); bit(1);
      word(((8192 - distance) << 3) | (length - 2));
    } else if (token.ext) {
      const [distance, length] = token.ext;
      bit(0); bit(1);
      word((8192 - distance) << 3);
      out.push(length - 1);
    } else if (token.end) {
      bit(0); bit(1);
      word(token.endWord ?? 0);
      out.push(0);
    } else {
      throw new Error('unknown token');
    }
  }
  // Unused bits of the last flag byte are ignored by the decoder; `padBits` lets a test make them non-zero.
  while (used < 8 && used > 0) {
    out[flagIndex] |= (padBits & 1) << (7 - used);
    used += 1;
  }
  return Uint8Array.from(out);
}

// Greedy parse with the longest match inside the 8192-byte window, length-2 references included.
export function packGreedy(data) {
  const positions = new Map();
  const tokens = [];
  let index = 0;
  const remember = (position) => {
    if (position + 1 >= data.length) return;
    const key = (data[position] << 8) | data[position + 1];
    if (!positions.has(key)) positions.set(key, []);
    positions.get(key).push(position);
  };
  while (index < data.length) {
    let bestLength = 0;
    let bestDistance = 0;
    const max = Math.min(256, data.length - index);
    if (max >= 2) {
      const list = positions.get((data[index] << 8) | data[index + 1]) ?? [];
      for (let at = list.length - 1; at >= 0 && index - list[at] <= 8192; at -= 1) {
        const distance = index - list[at];
        let length = 2;
        while (length < max && data[list[at] + length] === data[index + length]) length += 1;
        if (length > bestLength) { bestLength = length; bestDistance = distance; }
        if (length === max) break;
      }
    }
    const near = bestDistance <= 256 && bestLength <= 5;
    const worthIt = bestLength >= 3 || (bestLength === 2 && bestDistance <= 256);
    if (worthIt) {
      if (near) tokens.push({ near: [bestDistance, bestLength] });
      else if (bestLength <= 9) tokens.push({ word: [bestDistance, bestLength] });
      else tokens.push({ ext: [bestDistance, bestLength] });
      for (let step = 0; step < bestLength; step += 1) remember(index + step);
      index += bestLength;
    } else {
      tokens.push({ literal: data[index] });
      remember(index);
      index += 1;
    }
  }
  tokens.push({ end: true });
  return tsrStream(tokens);
}

// ---------------------------------------------------------------------------------------------------------------------
// ISO9660 volume

function bothEndian32(bytes, offset, value) {
  const view = new DataView(bytes.buffer, bytes.byteOffset);
  view.setUint32(offset, value, true);
  view.setUint32(offset + 4, value, false);
}

function directoryRecord({ lba, size, name, directory = false }) {
  const nameBytes = typeof name === 'string' ? Buffer.from(name, 'ascii') : Uint8Array.from(name);
  const length = 33 + nameBytes.length + ((33 + nameBytes.length) % 2);
  const record = new Uint8Array(length);
  record[0] = length;
  bothEndian32(record, 2, lba);
  bothEndian32(record, 10, size);
  record[25] = directory ? 0x02 : 0x00;
  record[32] = nameBytes.length;
  record.set(nameBytes, 33);
  return record;
}

export const DISC_LAYOUT = Object.freeze({ pvd: 16, directory: 18, face: 19, robot: 20, tsr: 21 });

// A MODE1/2352 volume with one directory that lists TSR.BIN, FACE.BIN and C_ROBOT.BIN.
//   slot      the bytes of TSR.BIN as the directory describes it (its length is the directory length)
//   padByte   what fills the rest of the last allocated sector after `slot` (zero in the accepted images)
// Right behind the TSR extent sits a sector range filled with 0xab: the next extent, which an export must never touch.
export function buildDisc({ slot, padByte = 0, product = null, extraFiles = [] }) {
  const allocated = Math.ceil(slot.length / USER);
  const next = DISC_LAYOUT.tsr + allocated;
  let total = next + 3;
  const added = extraFiles.map(file => {
    const entry = { ...file, lba: total }; total += Math.ceil(file.bytes.length / USER); return entry;
  });
  const user = Array.from({ length: total }, () => new Uint8Array(USER));
  const pvd = user[DISC_LAYOUT.pvd];
  pvd[0] = 1;
  pvd.set(Buffer.from('CD001'), 1);
  pvd[6] = 1;
  const block = new DataView(pvd.buffer);
  block.setUint16(128, USER, true);
  block.setUint16(130, USER, false);
  pvd.set(directoryRecord({ lba: DISC_LAYOUT.directory, size: USER, name: [0], directory: true }), 156);
  user[17][0] = 0xff;
  user[17].set(Buffer.from('CD001'), 1);
  user[17][6] = 1;
  const records = [
    directoryRecord({ lba: DISC_LAYOUT.directory, size: USER, name: [0], directory: true }),
    directoryRecord({ lba: DISC_LAYOUT.directory, size: USER, name: [1], directory: true }),
  ];
  let recordOffset = records[0].length + records[1].length;
  const tsrRecord = directoryRecord({ lba: DISC_LAYOUT.tsr, size: slot.length, name: 'TSR.BIN;1' });
  records.push(tsrRecord,
    directoryRecord({ lba: DISC_LAYOUT.face, size: 64, name: 'FACE.BIN;1' }),
    directoryRecord({ lba: DISC_LAYOUT.robot, size: 64, name: 'C_ROBOT.BIN;1' }));
  for (const file of added) records.push(directoryRecord({ lba: file.lba, size: file.bytes.length, name: `${file.name};1` }));
  user[DISC_LAYOUT.directory].set(Buffer.concat(records));
  // A Saturn disc header at the start of sector 0 when a product code is given (the editor reads it for personal images).
  if (product) user[0].set(Buffer.from(`SEGA SEGASATURN SEGA ENTERPRISES T-${product}`.padEnd(96, ' '), 'ascii'));
  user[DISC_LAYOUT.face].set(randomBytes(64, 1));
  user[DISC_LAYOUT.robot].set(randomBytes(64, 2));
  for (let sector = 0; sector < allocated; sector += 1) {
    const chunk = slot.subarray(sector * USER, (sector + 1) * USER);
    user[DISC_LAYOUT.tsr + sector].fill(padByte);
    user[DISC_LAYOUT.tsr + sector].set(chunk);
  }
  for (let sector = next; sector < next + 3; sector += 1) user[sector].fill(0xab);
  const modes = new Map();
  for (const file of added) {
    for (let i = 0; i < Math.ceil(file.bytes.length / USER); i++) {
      user[file.lba + i].set(file.bytes.subarray(i * USER, (i + 1) * USER));
      modes.set(file.lba + i, file.mode ?? 1);
    }
  }
  const image = new Uint8Array(total * SECTOR);
  user.forEach((data, lba) => image.set(modes.get(lba) === 2 ? referenceMode2Form1Sector(lba, data) : referenceMode1Sector(lba, data), lba * SECTOR));
  return Object.freeze({
    image,
    blob: new Blob([image]),
    slot,
    allocatedSectors: allocated,
    nextLba: next,
    tsrLba: DISC_LAYOUT.tsr,
    directoryLba: DISC_LAYOUT.directory,
    recordOffset,
    sha256: sha256(image),
    extraFiles: Object.freeze(added),
  });
}

export const sectorOf = (bytes, lba) => bytes.subarray(lba * SECTOR, (lba + 1) * SECTOR);

// A file's bytes as stored in an image: `length` bytes from the user data of the sectors that start at `lba`.
export function readFileBytes(image, lba, length) {
  const out = new Uint8Array(length);
  for (let sector = 0; sector * USER < length; sector += 1) {
    out.set(sectorOf(image, lba + sector).subarray(16, 16 + Math.min(USER, length - sector * USER)), sector * USER);
  }
  return out;
}

// The data length of the TSR.BIN directory record, read from both of its byte orders.
export function directoryLengths(image, disc) {
  const record = sectorOf(image, disc.directoryLba).subarray(16 + disc.recordOffset);
  const view = new DataView(record.buffer, record.byteOffset);
  return { little: view.getUint32(10, true), big: view.getUint32(14, false) };
}

// The first sectors that differ between two equally long images.
export function differingSectors(before, after) {
  const result = [];
  for (let lba = 0; lba * SECTOR < before.length; lba += 1) {
    if (!sameBytes(sectorOf(before, lba), sectorOf(after, lba))) result.push(lba);
  }
  return result;
}

// The session object inspectPatchedImage builds for an authenticated image. Provenance is a property of the real
// accepted images, so a synthetic disc gets its session assembled here from the same pieces.
export async function makeSession(disc, decoded, { gameId = 'srwf-final', compressedTsr } = {}) {
  const files = await locateIsoFiles(disc.blob);
  const root = splitRootSegments(decoded);
  const rows = buildEditorRows(root, decoded, gameId);
  const readOnly = (list) => new Map(list.filter((row) => !row.editable).map((row) => [row.recordIndex, row.readOnlyReason]));
  const session = Object.freeze({
    sessionToken: `${disc.sha256}:${files.tsr.extentLba}:${files.tsr.byteLength}:${decoded.length}`,
    sourceBlob: disc.blob,
    descriptor: Object.freeze({
      gameId, targetSize: disc.image.length, targetSha256: disc.sha256, baseTargetSha256: disc.sha256,
    }),
    file: files.tsr,
    compressedTsr: compressedTsr === undefined ? disc.slot.slice() : compressedTsr,
    decoded,
    root,
    readOnly: Object.freeze({ unit: readOnly(rows.units), pilot: readOnly(rows.pilots), weapon: readOnly(rows.weapons) }),
  });
  return { session, rows };
}

const UNIT_FIELDS = ['hp', 'en', 'armor', 'speed', 'limit', 'move', 'ground', 'sea', 'air', 'space',
  'ability1', 'ability2', 'ability3', 'ability4', 'abilityValue1', 'abilityValue2', 'abilityValue3', 'abilityValue4', 'shield', 'parry'];
const PILOT_FIELDS = ['exp', 'atk', 'shot', 'agi', 'hit', 'tech', 'cnt', 'mp', 'ground', 'sea', 'air', 'space',
  'attackGrowth', 'shotGrowth', 'hitGrowth', 'techGrowth', 'agiGrowth', 'cntGrowth', 'mindGrowth', 'syncGrowth'];
const WEAPON_FIELDS = ['attack', 'hit', 'critical', 'minRange', 'maxRange', 'terrain', 'energy', 'ammo', 'requiredMorale', 'requiredSkill'];
const pick = (row, fields) => Object.fromEntries(fields.map((field) => [field, row[field]]));

// A request that echoes every row of the session unchanged; `change(kind, row, fields)` may edit a copy of the fields.
export function echoRequest(session, rows, change = () => {}) {
  const edit = (kind, list, names, extra = () => ({})) => list.map((row) => {
    const fields = pick(row, names);
    change(kind, row, fields);
    return { recordIndex: row.recordIndex, fields, ...extra(row) };
  });
  return {
    sessionToken: session.sessionToken,
    unitEdits: edit('unit', rows.units, UNIT_FIELDS),
    pilotEdits: edit('pilot', rows.pilots, PILOT_FIELDS, (row) => ({
      specialAbilities: row.specialAbilities.map(({ id, level }) => ({ id, level })),
    })),
    weaponEdits: edit('weapon', rows.weapons, WEAPON_FIELDS),
  };
}

// A copy of `image` in which the user data of the given sectors is edited (`edits`: lba -> function(user) that changes the
// 2048 bytes in place) and the sectors are written again with correct checksums. Everything else stays byte for byte.
export function rewriteUserSectors(image, edits) {
  const copy = image.slice();
  for (const [lba, edit] of edits) {
    const user = sectorOf(copy, lba).slice(16, 16 + USER);
    edit(user);
    copy.set(referenceMode1Sector(lba, user), lba * SECTOR);
  }
  return copy;
}

// The same, for one byte range of the TSR extent counted from the start of the file: `bytes` replace the file bytes at `at`.
export function rewriteExtentBytes(image, extentLba, at, bytes) {
  const edits = new Map();
  for (let offset = 0; offset < bytes.length;) {
    const position = at + offset;
    const sector = Math.floor(position / USER);
    const within = position % USER;
    const take = Math.min(USER - within, bytes.length - offset);
    const chunk = bytes.subarray(offset, offset + take);
    edits.set(extentLba + sector, (user) => user.set(chunk, within));
    offset += take;
  }
  return rewriteUserSectors(image, edits);
}
